//! Explicit receive-only HID tasks; every operation stays on the native service path.
use super::*;

pub(super) fn catalogue() -> Vec<Value> {
    let selected=||vec![("interfaceId",string(128))];
    let capture=||fields(selected(),vec![("generation",string(128))]);
    let replay=||vec![("replayId",string(128))];
    let upload=||vec![("uploadId",string(128))];
    let cursor=||json!({"type":"string","minLength":1,"maxLength":20,"pattern":"^(0|[1-9][0-9]*)$"});
    let page=||vec![("offset",integer(0,1_000_000)),("limit",integer(1,128)),("contentFingerprint",string(64))];
    vec![
        tool("controller_hid_list","Enumerate native HID interfaces and metadata availability. A captureGeneration identifies an already open shared receive stream. This never opens a receiver. Native sensitive-device restrictions remain authoritative. Follow page.nextOffset using page.contentFingerprint.",page(),&[]),
        tool("controller_hid_inspect","Inspect the selected native HID descriptor and contractFingerprint without opening a receiver. Preserve native partial-capability failures and provenance.",selected(),&["interfaceId"]),
        tool("controller_hid_catalog","List cached last-observed HID descriptor summaries. Offline snapshots do not establish current device availability and never start discovery or capture. Follow page.nextOffset with its contentFingerprint.",page(),&[]),
        tool("controller_hid_snapshot","Read the full cached last-observed descriptor by interfaceId or snapshotId supplied as interfaceId. This reads process-local cached evidence; it does not probe or open a device.",selected(),&["interfaceId"]),
        tool("controller_hid_open","Explicitly open one selected receive-only HID capture. Optional contractFingerprint fences the inspected contract. Returns the native generation; retain it for state/reports/get/close. Native access-denied and metadata-only devices remain unavailable. Close your capture when finished.",fields(selected(),vec![("contractFingerprint",string(128))]),&["interfaceId"]),
        tool("controller_hid_state","Read the native decoded current state for an exact selected capture generation. Unknown/unavailable/stale values, diagnostics and terminal failures are native evidence. This does not open a capture or reconstruct reports. Page values using offset, limit and contentFingerprint.",fields(capture(),page()),&["interfaceId","generation"]),
        tool("controller_hid_reports","Read a bounded native report page for an exact capture generation; after is an unsigned decimal cursor. Preserve repeated packets, gap and terminal evidence. Share the same captureGeneration as the UI; do not open a second receive stream.",fields(capture(),vec![("limit",integer(1,128)),("after",json!({"type":"string","minLength":1,"maxLength":20,"pattern":"^(0|[1-9][0-9]*)$"}))]),&["interfaceId","generation"]),
        tool("controller_hid_capture_status","Read the exact receiver generation's status, retained cursor range and terminal reason without fetching reports. To pause observation retain your cursor and stop calling reports; resume with the last observed sequence.",capture(),&["interfaceId","generation"]),
        tool("controller_hid_report_slice","Read exact retained report JSON bytes by sequence, fenced by capture generation. Concatenate base64-decoded data at nextOffset until done. Evicted reports are unavailable.",fields(capture(),vec![("sequence",cursor()),("offset",integer(0,67_108_864)),("limit",integer(1,32_768))]),&["interfaceId","generation","sequence","offset","limit"]),
        tool("controller_hid_inspection_slice","Read exact UTF-8 JSON bytes for a large native observation. Choose list/catalog, inspect/snapshot with interfaceId, state with interfaceId and generation, or replay_read with replayId and part. Supply the returned contentFingerprint on every continuation; restart after a stale-content error.",vec![("source",choice(&["list","catalog","inspect","snapshot","state","replay_read"])),("interfaceId",string(128)),("generation",string(128)),("replayId",string(128)),("part",choice(&["descriptor","state"])),("after",cursor()),("elapsedUs",cursor()),("seek",json!({"type":"boolean"})),("offset",integer(0,268_435_456)),("limit",integer(1,32_768)),("contentFingerprint",string(64)),("contractFingerprint",string(128)),("snapshotId",string(128))],&["source","offset","limit"]),
        tool("controller_hid_get","Explicit bounded input/feature GET on an existing receive-only HID generation. This sends no output report. Use a unique requestId; native support, sensitive-device restrictions, report bounds and deadlines remain authoritative.",fields(capture(),vec![("requestId",string(128)),("kind",choice(&["input","feature"])),("reportId",integer(0,255)),("maxBytes",integer(1,65536)),("deadlineMs",integer(1,2000))]),&["interfaceId","generation","requestId","kind","reportId","maxBytes","deadlineMs"]),
        tool("controller_hid_get_slice","Read exact JSON bytes of a retained GET result by its requestId and generation. This only reads retained evidence. Another admitted GET replaces the previous result; fetching a slice never repeats the device request.",fields(capture(),vec![("requestId",string(128)),("offset",integer(0,67_108_864)),("limit",integer(1,32_768))]),&["interfaceId","generation","requestId","offset","limit"]),
        tool("controller_hid_close","Close the exact selected HID capture generation you opened. This retires its receiver; a stale generation cannot close a replacement. Do not close a shared capture owned by another workflow.",capture(),&["interfaceId","generation"]),
        tool("controller_hid_record_list","List retained recordings and their source identities, including sealed recordings from retired captures.",vec![],&[]),
        tool("controller_hid_record_start","Record subsequent native reports independently of inspector polling. Optional maxBytes and maxRecords lower the native capacity limits. Retain the capture identity for stop and export.",fields(capture(),vec![("maxBytes",integer(16_384,67_108_864)),("maxRecords",integer(3,1_000_000))]),&["interfaceId","generation"]),
        tool("controller_hid_record_status","Read recording status, capacity, stop reason and last sequence for this generation.",capture(),&["interfaceId","generation"]),
        tool("controller_hid_record_stop","Seal the recording and retain its ordered records for export.",capture(),&["interfaceId","generation"]),
        tool("controller_hid_record_export","Download a sealed archive in bounded base64 chunks. Start at offset 0 and continue at nextOffset until totalBytes. Preserve the bytes exactly for import.",fields(capture(),vec![("offset",integer(0,67_108_864)),("limit",integer(1,32_768))]),&["interfaceId","generation","offset","limit"]),
        tool("controller_hid_record_discard","Release a sealed recording after export. A live capture can start another recording after discard.",capture(),&["interfaceId","generation"]),
        tool("controller_hid_replay_upload_start","Reserve a bounded upload for an exported recording. Retain uploadId and send consecutive base64 chunks with exact byte offsets.",vec![("totalBytes",integer(1,67_108_864))],&["totalBytes"]),
        tool("controller_hid_replay_upload_chunk","Append up to 24576 recording bytes at an exact offset under the initiating client identity.",fields(upload(),vec![("offset",integer(0,67_108_864)),("chunk",string(32_768))]),&["uploadId","offset","chunk"]),
        tool("controller_hid_replay_upload_finish","Validate the completed recording and open an observation-only replay. Retain replayId to inspect records and close it.",upload(),&["uploadId"]),
        tool("controller_hid_replay_upload_cancel","Release an unfinished recording upload.",upload(),&["uploadId"]),
        tool("controller_hid_replay_read","Read ordered imported records at a decimal entry cursor and optional elapsed microseconds. Set seek=true with elapsedUs to inspect state at an absolute replay time. Repeat the same cursor and clock for deterministic replay. For exact archive slices use part recording, byteOffset and maxBytes.",fields(replay(),vec![("after",cursor()),("limit",integer(1,128)),("elapsedUs",cursor()),("seek",json!({"type":"boolean"})),("part",choice(&["recording","state","descriptor"])),("byteOffset",integer(0,67_108_864)),("maxBytes",integer(1,24_576))]),&["replayId"]),
        tool("controller_hid_replay_close","Release imported replay data from memory.",replay(),&["replayId"]),
    ]
}
